<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(404);exit;}
function platformVariantEligible(array $v): bool{return (bool)$v['active']&&(bool)$v['authorized']&&(int)$v['price_cents']>0&&(!$v['company_id']||($v['company_status']??'')==='verified');}
function platformVariants(string $product): array{$rows=accountQuery('SELECT v.*,c.status AS company_status FROM idea_commerce_variants v LEFT JOIN idea_companies c ON c.id=v.company_id WHERE v.product_id=? ORDER BY v.label',[$product])->fetchAll();$result=[];foreach($rows as $v){if(!platformVariantEligible($v))continue;$v['available_milli']=max(0,(int)$v['stock_milli']-(int)$v['reserved_milli']);unset($v['evidence'],$v['reserved_milli'],$v['stock_milli']);$result[]=$v;}return $result;}
function platformCart(array $u): array{
 $items=accountQuery('SELECT i.quantity_milli,v.*,c.status AS company_status FROM idea_cart_items i JOIN idea_commerce_variants v ON v.id=i.variant_id LEFT JOIN idea_companies c ON c.id=v.company_id WHERE i.user_id=? ORDER BY v.id',[$u['id']])->fetchAll();$subtotal=0;$tax=0;
 foreach($items as &$i){$i['product']=platformProduct($i['product_id']);$i['eligible']=platformVariantEligible($i);$i['available_milli']=max(0,(int)$i['stock_milli']-(int)$i['reserved_milli']);$i['line_cents']=intdiv((int)$i['price_cents']*(int)$i['quantity_milli']+500,1000);$i['tax_cents']=intdiv($i['line_cents']*(int)$i['tax_basis_points']+5000,10000);$subtotal+=$i['line_cents'];$tax+=$i['tax_cents'];unset($i['evidence'],$i['reserved_milli'],$i['stock_milli']);}return ['items'=>$items,'subtotal_cents'=>$subtotal,'tax_cents'=>$tax,'currency'=>'EGP'];
}
function platformReleaseReservation(array $order): void{
 foreach(accountQuery('SELECT variant_id,quantity_milli FROM idea_order_items WHERE order_id=? ORDER BY variant_id',[$order['id']])->fetchAll() as $i)accountQuery('UPDATE idea_commerce_variants SET reserved_milli=reserved_milli-? WHERE id=? AND reserved_milli>=?',[(int)$i['quantity_milli'],$i['variant_id'],(int)$i['quantity_milli']]);
}
function platformExpireOrders(): void{
 $rows=accountQuery("SELECT id FROM idea_orders WHERE status='awaiting_payment' AND reservation_expires_at<? LIMIT 50",[platformNow()])->fetchAll();foreach($rows as $r)platformTransaction(function()use($r){$o=accountQuery('SELECT * FROM idea_orders WHERE id=?'.platformLock(),[$r['id']])->fetch();if(!$o||$o['status']!=='awaiting_payment'||$o['reservation_expires_at']>=platformNow())return;platformReleaseReservation($o);accountQuery("UPDATE idea_orders SET status='expired',payment_status='expired',reservation_expires_at=NULL,updated_at=? WHERE id=?",[platformNow(),$o['id']]);});
}
function platformOrder(array $u,string $id): array{
 $o=accountQuery('SELECT * FROM idea_orders WHERE id=?',[$id])->fetch();if(!$o)accountError(404,'ORDER_NOT_FOUND');$items=accountQuery('SELECT * FROM idea_order_items WHERE order_id=?',[$id])->fetchAll();$supplier=null;
 if($u['role']==='supplier'){$supplier=accountCompany($u);if($supplier['status']!=='verified')accountError(403,'VERIFIED_COMPANY_REQUIRED');$items=array_values(array_filter($items,fn($i)=>$i['company_id']===$supplier['id']));if(!$items)accountError(404,'ORDER_NOT_FOUND');}
 elseif($u['role']!=='admin'&&$o['user_id']!==$u['id'])accountError(404,'ORDER_NOT_FOUND');
 foreach($items as &$i)$i['product_snapshot']=json_decode($i['product_snapshot'],true);$o['items']=$items;$o['address_snapshot']=json_decode($o['address_snapshot'],true);$o['delivery']=accountQuery('SELECT id,provider,tracking_number,status,history,updated_at FROM idea_deliveries WHERE order_id=?',[$id])->fetch()?:null;if($o['delivery'])$o['delivery']['history']=json_decode($o['delivery']['history'],true);
 $o['invoice']=accountQuery('SELECT id,invoice_number,status,snapshot,issued_at FROM idea_invoices WHERE order_id=?',[$id])->fetch()?:null;if($o['invoice'])$o['invoice']['snapshot']=json_decode($o['invoice']['snapshot'],true);
 if($supplier){unset($o['total_cents'],$o['subtotal_cents'],$o['tax_cents'],$o['shipping_cents'],$o['invoice']);}else{$o['payments']=accountQuery('SELECT id,provider,status,amount_cents,currency,created_at FROM idea_payments WHERE order_id=? ORDER BY created_at DESC',[$id])->fetchAll();$o['refunds']=accountQuery('SELECT id,amount_cents,reason,status,created_at FROM idea_refunds WHERE order_id=?',[$id])->fetchAll();}return $o;
}
function platformCreateInvoice(array $o): void{if(accountQuery('SELECT id FROM idea_invoices WHERE order_id=?',[$o['id']])->fetch())return;$id=platformId();$items=accountQuery('SELECT product_snapshot,quantity_milli,unit_price_cents,subtotal_cents,tax_cents FROM idea_order_items WHERE order_id=?',[$o['id']])->fetchAll();$snapshot=['order'=>$o,'items'=>$items];accountQuery('INSERT INTO idea_invoices(id,order_id,invoice_number,status,snapshot,issued_at) VALUES(?,?,?,?,?,?)',[$id,$o['id'],'IDEA-'.date('Ymd').'-'.strtoupper(substr($o['id'],0,12)),'issued',platformJson($snapshot),platformNow()]);}
function platformCommerceAction(string $a,array $d,array $u): array{
 if($a==='cart'){platformExpireOrders();return platformCart($u);}
 if($a==='cart-set'){
  if($u['role']!=='buyer')accountError(403,'CUSTOMER_ONLY');$variant=accountString($d,'variant_id',32,true);$qty=platformInt($d,'quantity_milli',0,100000000);return platformTransaction(function()use($u,$variant,$qty){accountQuery('SELECT id FROM idea_users WHERE id=?'.platformLock(),[$u['id']]);$v=accountQuery('SELECT v.*,c.status AS company_status FROM idea_commerce_variants v LEFT JOIN idea_companies c ON c.id=v.company_id WHERE v.id=?',[$variant])->fetch();if(!$v)accountError(404,'VARIANT_NOT_FOUND');if($qty&&(!platformVariantEligible($v)||$qty>(int)$v['stock_milli']-(int)$v['reserved_milli']))accountError(409,'PRODUCT_UNAVAILABLE');if($v['unit']==='pieces'&&$qty%1000)accountError(422,'WHOLE_QUANTITY_REQUIRED');accountQuery('DELETE FROM idea_cart_items WHERE user_id=? AND variant_id=?',[$u['id'],$variant]);if($qty)accountQuery('INSERT INTO idea_cart_items(user_id,variant_id,quantity_milli,updated_at) VALUES(?,?,?,?)',[$u['id'],$variant,$qty,platformNow()]);return ['saved'=>true];});
 }
 if($a==='checkout-options')return ['features'=>platformFeatures(),'addresses'=>accountQuery('SELECT * FROM idea_addresses WHERE user_id=?',[$u['id']])->fetchAll(),'shipping_methods'=>accountQuery('SELECT * FROM idea_shipping_methods WHERE active=1 ORDER BY name')->fetchAll(),'email_verified'=>(bool)platformSecurity($u)['email_verified_at']];
 if($a==='checkout'){
  if($u['role']!=='buyer')accountError(403,'CUSTOMER_ONLY');if(!platformSecurity($u)['email_verified_at'])accountError(403,'EMAIL_VERIFICATION_REQUIRED');$method=accountString($d,'payment_method',32,true);$features=platformFeatures();if(($method==='paymob'&&!$features['payments']['configured'])||($method==='cash_on_delivery'&&!$features['cod_enabled'])||!in_array($method,['paymob','cash_on_delivery'],true))accountError(503,'PAYMENT_METHOD_NOT_CONFIGURED');$key=accountString($d,'idempotency_key',100,true);if(!preg_match('/^[a-zA-Z0-9_-]{16,100}$/D',$key))accountError(422,'INVALID_IDEMPOTENCY_KEY');platformExpireOrders();
  return platformTransaction(function()use($u,$d,$method,$key){accountQuery('SELECT id FROM idea_users WHERE id=?'.platformLock(),[$u['id']]);$old=accountQuery('SELECT id FROM idea_orders WHERE user_id=? AND idempotency_key=?',[$u['id'],$key])->fetch();if($old)return ['id'=>$old['id'],'reused'=>true];
   $address=accountQuery('SELECT * FROM idea_addresses WHERE id=? AND user_id=?',[accountString($d,'address_id',32,true),$u['id']])->fetch();if(!$address)accountError(422,'ADDRESS_REQUIRED');$shipping=accountQuery('SELECT * FROM idea_shipping_methods WHERE id=? AND active=1',[accountString($d,'shipping_method_id',32,true)])->fetch();if(!$shipping||!in_array($shipping['governorate'],['*',$address['governorate']],true))accountError(422,'SHIPPING_UNAVAILABLE');
   $cart=platformCart($u);if(!$cart['items'])accountError(422,'CART_EMPTY');$subtotal=0;$tax=0;foreach($cart['items'] as &$item){$v=accountQuery('SELECT v.*,c.status AS company_status FROM idea_commerce_variants v LEFT JOIN idea_companies c ON c.id=v.company_id WHERE v.id=?'.platformLock(),[$item['id']])->fetch();if(!$v||!platformVariantEligible($v)||(int)$item['quantity_milli']>(int)$v['stock_milli']-(int)$v['reserved_milli'])accountError(409,'PRODUCT_UNAVAILABLE');$item['unit_price_cents']=(int)$v['price_cents'];$item['line_cents']=intdiv($item['unit_price_cents']*(int)$item['quantity_milli']+500,1000);$item['tax_cents']=intdiv($item['line_cents']*(int)$v['tax_basis_points']+5000,10000);$subtotal+=$item['line_cents'];$tax+=$item['tax_cents'];}
   unset($item);$id=platformId();$now=platformNow();$cod=$method==='cash_on_delivery';$total=$subtotal+$tax+(int)$shipping['price_cents'];
   accountQuery('INSERT INTO idea_orders(id,user_id,idempotency_key,status,payment_status,payment_method,currency,subtotal_cents,tax_cents,shipping_cents,total_cents,address_snapshot,shipping_method_id,reservation_expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$u['id'],$key,$cod?'confirmed':'awaiting_payment','unpaid',$method,'EGP',$subtotal,$tax,$shipping['price_cents'],$total,platformJson($address),$shipping['id'],$cod?null:$now+1800000,$now,$now]);
   foreach($cart['items'] as $i){accountQuery('INSERT INTO idea_order_items(id,order_id,variant_id,company_id,product_snapshot,quantity_milli,unit_price_cents,subtotal_cents,tax_cents) VALUES(?,?,?,?,?,?,?,?,?)',[platformId(),$id,$i['id'],$i['company_id'],platformJson($i['product']+['sku'=>$i['sku'],'variant'=>$i['label'],'unit'=>$i['unit']]),$i['quantity_milli'],$i['unit_price_cents'],$i['line_cents'],$i['tax_cents']]);accountQuery($cod?'UPDATE idea_commerce_variants SET stock_milli=stock_milli-? WHERE id=?':'UPDATE idea_commerce_variants SET reserved_milli=reserved_milli+? WHERE id=?',[$i['quantity_milli'],$i['id']]);}
   accountQuery('DELETE FROM idea_cart_items WHERE user_id=?',[$u['id']]);$order=accountQuery('SELECT * FROM idea_orders WHERE id=?',[$id])->fetch();if($cod)platformCreateInvoice($order);platformNotify($u['id'],'order-created:'.$id,'IDEA — Order received','Order '.$id.' has been recorded. Payment status: unpaid.','/account/orders/'.$id);return ['id'=>$id,'status'=>$order['status']];
  });
 }
 if($a==='orders'){
  if($u['role']==='admin')$rows=accountQuery('SELECT id FROM idea_orders ORDER BY created_at DESC LIMIT 200')->fetchAll();elseif($u['role']==='supplier'){$c=accountCompany($u);$rows=accountQuery('SELECT DISTINCT o.id,o.created_at FROM idea_orders o JOIN idea_order_items i ON i.order_id=o.id WHERE i.company_id=? ORDER BY o.created_at DESC',[$c['id']])->fetchAll();}else $rows=accountQuery('SELECT id FROM idea_orders WHERE user_id=? ORDER BY created_at DESC LIMIT 100',[$u['id']])->fetchAll();return ['orders'=>array_map(fn($r)=>platformOrder($u,$r['id']),$rows)];
 }
 if($a==='order')return platformOrder($u,accountString($d,'id',32,true));
 if($a==='order-cancel-request'){$o=platformOrder($u,accountString($d,'id',32,true));if($o['user_id']!==$u['id'])accountError(403,'FORBIDDEN');if(in_array($o['status'],['cancelled','expired','delivered'],true))accountError(409,'ORDER_STATE_INVALID');accountQuery('UPDATE idea_orders SET cancellation_requested_at=? WHERE id=?',[platformNow(),$o['id']]);platformAudit($u,'order-cancel-request',$o['id']);return ['requested'=>true];}
 if($a==='admin-order-state'){
  platformAdmin($u);$id=accountString($d,'id',32,true);$state=accountString($d,'status',32,true);return platformTransaction(function()use($id,$state,$u){$o=accountQuery('SELECT * FROM idea_orders WHERE id=?'.platformLock(),[$id])->fetch();if(!$o)accountError(404,'ORDER_NOT_FOUND');$next=['confirmed'=>['processing','cancelled'],'processing'=>['ready_to_ship','cancelled'],'ready_to_ship'=>['shipped','cancelled'],'shipped'=>['delivered'],'awaiting_payment'=>['cancelled']];if(!in_array($state,$next[$o['status']]??[],true))accountError(409,'ORDER_TRANSITION_INVALID');if($state!=='cancelled'&&$o['payment_method']!=='cash_on_delivery'&&$o['payment_status']!=='paid')accountError(409,'PAYMENT_REQUIRED');if($state==='cancelled'){if($o['payment_status']==='paid')accountError(409,'REFUND_REQUIRED_BEFORE_CANCELLATION');if($o['status']==='awaiting_payment')platformReleaseReservation($o);else foreach(accountQuery('SELECT variant_id,quantity_milli FROM idea_order_items WHERE order_id=?',[$id])->fetchAll() as $i)accountQuery('UPDATE idea_commerce_variants SET stock_milli=stock_milli+? WHERE id=?',[$i['quantity_milli'],$i['variant_id']]);}accountQuery('UPDATE idea_orders SET status=?,reservation_expires_at=NULL,updated_at=? WHERE id=?',[$state,platformNow(),$id]);platformAudit($u,'order-'.$state,$id);platformNotify($o['user_id'],'order-state:'.$id.':'.platformNow(),'IDEA — Order update',$state,'/account/orders/'.$id);return ['status'=>$state];});
 }
 accountError(404,'UNKNOWN_ACTION');
}
